test('overlapping NSAID and steroid warns, separate phases do not claim safe',()=>{let r=C.reviewPrescription({rows:[row('meloxicam'),row('pds')],species:'dog',weight:5,checks});assert.ok(r.findings.some(x=>x.code==='nsaid-steroid'));assert.ok(r.findings.find(x=>x.code==='nsaid-steroid').source.startsWith('https://www.fda.gov/'));r=C.reviewPrescription({rows:[row('meloxicam'),row('pds',{startDay:8})],species:'dog',weight:5,checks});assert.ok(!r.findings.some(x=>x.code==='nsaid-steroid'));assert.match(r.coverage,/휴약기간/);assert.doesNotMatch(r.summary,/안전|문제 없음/);});
test('EOD phases compare actual dates and retain unknown schedules as incomplete',()=>{assert.equal(C.overlaps(row('pds',{intervalDays:2,firstDoseDay:1}),row('pds',{intervalDays:2,firstDoseDay:2})),false);assert.equal(C.doseDays(row('pds',{firstDoseDay:3})),null);assert.equal(C.doseDays(row('pds',{startDay:0})),null);assert.equal(C.overlaps(row('pds',{days:''}),row('pds')),true);});
test('canonical duplicate, species, inputs and patient risks stay visible',()=>{const r=C.reviewPrescription({rows:[row('pds'),row('프레드니솔론'),row('meloxicam',{doseSpecies:'cat',strength:0})],species:'dog',weight:0,checks:{...checks,renal:'present'}});for(const code of ['duplicate','species-mismatch','strength','weight','nsaid-renal'])assert.ok(r.findings.some(x=>x.code===code),code);});
test('unsupported substances and missing patient history are explicit',()=>{const r=C.reviewPrescription({rows:[row('unknown')]});assert.deepEqual(r.unknown,['unknown']);assert.ok(r.findings.filter(x=>x.code.startsWith('patient-')).length===6);assert.match(r.coverage,/전체 상호작용/);});
test('handoff retains overdue and held work but excludes completed and omitted',()=>{const tasks=['planned','held','done','omitted'].map(status=>({status,plannedAt:'2020-01-01T00:00:00Z'}));assert.equal(C.taskState(tasks[0]),'late');assert.deepEqual(C.handoffTasks(tasks).map(x=>x.status),['planned','held']);});
test('seven starters have sources, species restrictions and editable stage schedules',()=>{assert.equal(starters.length,7);for(const t of starters){assert.equal(t.body.steps.length,6);assert.ok(t.body.sources.every(s=>s.url.startsWith('https://')&&s.reviewedDate==='2026-10-27'));assert.match(t.body.summary,/초안/);}assert.equal(starters.find(x=>x.id==='imha').body.species,'dog');assert.equal(starters.find(x=>x.id==='pancreatitis').body.species,'cat');});

let browser,server,origin,base;const root=path.resolve(__dirname,'..'),workerRoot=process.env.TRAINING_WORKER_ROOT||path.resolve(root,'../carestep-ai-api');
before(async()=>{({fixture:base}=await import(require('node:url').pathToFileURL(path.join(workerRoot,'test/helpers/practice-fixture.mjs')).href));const {chromium}=require('playwright');browser=await chromium.launch({...(process.env.HQ_TEST_BROWSER?{executablePath:process.env.HQ_TEST_BROWSER}:{}),headless:true});server=http.createServer((req,res)=>{const name=decodeURIComponent(req.url.split('?')[0]);const target=path.resolve(root,'.'+name);if(!target.startsWith(root+path.sep)){res.writeHead(403).end();return;}try{const body=fs.readFileSync(target);res.setHeader('Content-Type',({'.html':'text/html','.js':'application/javascript','.css':'text/css','.json':'application/json'})[path.extname(target)]||'application/octet-stream');res.end(body);}catch{res.writeHead(404).end();}});await new Promise(r=>server.listen(0,'127.0.0.1',r));origin='http://127.0.0.1:'+server.address().port;});
