async function wardManage(p){const d=p.locator('.cl-patient-manage');if(await d.count()&&!await d.evaluate(e=>e.open))await d.locator('summary').first().click();}
async function wardSettled(p){await p.waitForFunction(()=>document.querySelector('[data-cl-action=refresh]')?.disabled===false);}
async function show(p,selector){const l=p.locator(selector).first();while(await l.locator('xpath=ancestor::details[not(@open)]').count())await l.locator('xpath=ancestor::details[not(@open)]').first().locator(':scope > summary').click();return l;}
async function openSettings(p){await (await show(p,'[data-ar=marker]')).click();await p.locator('.cl-dialog [name=marker]').selectOption('settings');}
async function confirmRecord(d){const c=d.locator('[name=confirm]');if(await c.isVisible())await c.check();}
async function wardSave(p,label='저장'){await p.locator('.cl-dialog [type=submit]').first().click();await p.locator('.cl-dialog').waitFor({state:'hidden'});await wardSettled(p);}
