 for(let i=0;i<2;i++){const result=await api('/cases','POST',{requestKey:'summary-case-00'+i,roomId:rs[i].id,roomRevision:rs[i].revision,kind:'admission',species:'dog',weight:5,quickPatient:{name:'합성 환자 '+(i+1)}});ctx.caseIds.push(result.id);}
