async function scheduleFixture(t,width=1440){
 const ctx=await summaryFixture(t,width),{p,api,caseIds}=ctx,id=caseIds[0],day=new Date(Date.now()+86400000).toISOString().slice(0,10),at=day+'T10:30:00+09:00';let seq=0;
 const event=async(kind,data)=>api('/cases/'+id+'/events','POST',{revision:(await api('/cases/'+id)).item.revision,requestKey:'schedule-browser-'+(++seq),kind,data});
 for(let i=0;i<3;i++)await event('order.add',{title:'Synthetic injection '+i,category:'injection',plannedAt:at,confirm:true,medication:{drug:'Synthetic injection '+i,dose:10,doseUnit:'mg',strength:10,strengthUnit:'mg',amount:1,amountUnit:'mL',route:'IV'}});
 let r=await api('/cases/'+id);await event('task.record',{taskId:r.item.body.tasks[2].id,status:'done',actualAt:new Date().toISOString()});
 await event('order.add',{title:'Synthetic dressing',category:'procedure',plannedAt:at,confirm:true});
 await (await show(p,'[data-cl-action=refresh]')).click();await wardSettled(p);await p.locator('[data-cl-action=ward-board-mode][data-id=timeline]').click();await p.locator('[name=calendarDate]').fill(day);await p.locator('[name=calendarDate]').dispatchEvent('change');
 await p.locator('[name=calendarRange]').selectOption('all');return {...ctx,id,day,at,event};
}
